      "id": 29,
      "question": "<div style='margin-bottom:6px;font-weight:600;'>What is the number of regional offices of National council for Teacher Education? राररीय अज्यापक \nजजक्षा पररषद (NCTE) के क्षेत्रीय कायाणलयों की संख्या जकतनी है ?</div>",
      "questionHi": "What is the number of regional offices of National council for Teacher Education? राररीय अज्यापक \nजजक्षा पररषद (NCTE) के क्षेत्रीय कायाणलयों की संख्या जकतनी है ?",
