    {
      "id": 30,
      "question": "<div style='margin-bottom:6px;font-weight:600;'>Who among the following thinkers accepted education as process of human creation? जनम्नजलजखत \nजवचारकों में से कौन जजक्षा को मानव जनमाणर् की प्रजजया के रूप में स्वीकार जकया ?</div>",
      "questionHi": "Who among the following thinkers accepted education as process of human creation? जनम्नजलजखत \nजवचारकों में से कौन जजक्षा को मानव जनमाणर् की प्रजजया के रूप में स्वीकार जकया ?",
      "questionEn": "Who among the following thinkers accepted education as process of human creation? धनम्नधलधखत \nधवचारकों में से कौन धिक्षा को मानव धनमाणर् की प्रधिया के रूप में स्वीकार धकया ?",
      "options": [
        "Leave them free to play/उन्हें खेलने के जलए स्वतंत्र छोड़ दें।<br><span style='font-size:0.88em;color:#555;'>Mahatma Gandhi/महात्मा गााँिी</span>",
        "Keep their economic status in mind/उनकी आजथणक जस्थजत को ज्यान में रखें।<br><span style='font-size:0.88em;color:#555;'>Tagore/िैगोर</span>",
        "Give ample opportunity to debate/वाद-जववाद का पयाणप्त अवसर दें।<br><span style='font-size:0.88em;color:#555;'>Aurobindo/अरधवंदो</span>",
        "Study their socio-emotional development and motivate them towards interpersonal relations /उनके \nसामाजजक संवेगात्मक जवकास का अज्ययन करें तथा अन्ताः वैयजजक संबंजों की ओर प्रेररत करे।<br><span style='font-size:0.88em;color:#555;'>3. Who among the following thinkers accepted education as process of human creation? धनम्नधलधखत \nधवचारकों में से कौन धिक्षा को मानव धनमाणर् की प्रधिया के रूप में स्वीकार धकया ?</span>"
      ],
      "correctAnswer": 3,
      "correctLetter": "D",
      "examDate": "10.09.2020",
      "shift": "Shift-1",
      "originalQuestionNumber": 3
    }
