      "question": "<div style='margin-bottom:6px;font-weight:600;'>\"Children construct their own understanding through interaction with their own environment\" who \nsaid this? \"जच्चे अपने वातावरण के सार्थ सम्बन्ज जनाते हुए अपनी समझ का बवकास कर लेते हैं\" बकसने कहा ?</div>",
      "questionHi": "\"Children construct their own understanding through interaction with their own environment\" who \nsaid this? \"जच्चे अपने वातावरण के सार्थ सम्बन्ज जनाते हुए अपनी समझ का बवकास कर लेते हैं\" बकसने कहा ?",
