      "id": 8,
      "question": "<div style='margin-bottom:6px;font-weight:600;'>Effective learning depends most upon \nप्रभावी अबजगम बनम्नबलष्क्रखत में से बकस पर सवाणबजक बनभणर करता है ?</div>",
