      "id": 12,
      "question": "<div style='margin-bottom:6px;font-weight:600;'>The LCM of two numbers is 1820 and their HCF is 26. If one number is 130, then the other \nnumber is \nदव संख्याओं का लघुतम समापवत्यण 1820 तर्था महजम समापवतणक 26 है। यबद एक संख्या 130 है, तव दूसरी \nसंख्या है</div>",
